values.content:
You extract wholesale purchase orders into strict JSON.

From this PO email + attachment text, return ONLY JSON with this shape:
{
  "po_number": "string or empty",
  "buyer": { "company": "string", "email": "string", "phone": "string" },
  "terms": "net-15 | net-30 | net-60 | due-on-receipt",
  "lines": [
    { "sku": "", "title": "", "variant_title": "", "quantity": 0, "unit_price": 0.0, "case_pack": null }
  ]
}

Rules: convert cases to units ('4 cases of 12' -> quantity 48, case_pack 12); quantity is always an integer; unit_price is a number or null; keep SKU text exactly as printed; if a line is unreadable, include it with title and quantity 0 so a human sees it.

PO EMAIL:
Subject: {{ $json.subject }}
From: {{ $json.from }}
Body: {{ $json.textBody || $json.html || '' }}
Attachment text: {{ $('PO Text (PDF/DOCX)').item.json.text || $('PO Text (PDF/DOCX)').item.json.data || '' }}

parameters.jsCode:
// Normalize AI output into a clean PO object (works with OpenAI/Anthropic node shapes)
const raw = $input.first().json;
let out = raw?.output ?? raw?.message?.content ?? raw;
if (typeof out === 'string') {
  try { out = JSON.parse(out); }
  catch (e) {
    const m = out.match(/\{[\s\S]*\}/);
    out = m ? JSON.parse(m[0]) : { lines: [] };
  }
}
const lines = (out.lines ?? out.items ?? [])
  .map((l) => ({
    sku: (l.sku ?? '').toString().trim(),
    title: (l.title ?? l.product ?? '').toString().trim(),
    variant_title: (l.variant_title ?? l.variant ?? '').toString().trim(),
    quantity: parseInt(l.quantity ?? l.qty ?? 0, 10) || 0,
    unit_price: l.unit_price != null && l.unit_price !== '' ? parseFloat(l.unit_price) || undefined : undefined,
    case_pack: l.case_pack ? parseInt(l.case_pack, 10) || undefined : undefined,
  }))
  .filter((l) => (l.sku || l.title) && l.quantity > 0);

if (lines.length === 0) {
  throw new Error('No readable line items in PO email — skipped (check the AI node output).');
}
return [{ json: {
  po_number: (out.po_number ?? '').toString().trim(),
  buyer: out.buyer ?? {},
  terms: out.terms ?? 'net-30',
  lines,
} }];

// Match the PO line to a Shopify variant, price it wholesale, collect warnings.
const WHOLESALE_MULTIPLIER = 0.6; // <-- your default wholesale = 40% off catalog. Change me.
const line = $('Split Lines').item.json;
const products = $json?.data?.products?.nodes ?? [];

let variant = null, product = null;
outer: for (const p of products) {
  for (const v of p.variants.nodes) {
    if (line.sku && (v.sku || '').toLowerCase() === line.sku.toLowerCase()) { variant = v; product = p; break outer; }
  }
}
if (!variant && products.length) {
  product = products[0];
  const vs = product.variants.nodes;
  variant = (line.variant_title && vs.find(v => (v.title || '').toLowerCase().includes(line.variant_title.toLowerCase()))) || (vs.length === 1 ? vs[0] : vs[0]);
}
if (!variant) return [{ json: { line_item: null, error: 'no_match', line } }];

const catalog = parseFloat(variant.price) || 0;
const suggested = Math.round(catalog * WHOLESALE_MULTIPLIER * 100) / 100;
const unitPrice = line.unit_price ?? suggested;
const warnings = [];
if (line.unit_price != null && Math.abs(line.unit_price - suggested) > 0.02) warnings.push(`price_mismatch: PO ${line.unit_price} vs suggested ${suggested}`);
if (line.quantity > (variant.inventoryQuantity ?? 0)) warnings.push(`low_inventory: ordered ${line.quantity}, on hand ${variant.inventoryQuantity}`);
if (line.case_pack && line.quantity % line.case_pack !== 0) warnings.push(`case_pack: qty ${line.quantity} not a multiple of ${line.case_pack}`);

return [{ json: {
  line_item: { variantId: variant.id, quantity: line.quantity, originalUnitPrice: String(unitPrice) },
  warnings, sku: variant.sku, product_title: product?.title,
} }];

// Assemble the draftOrderCreate GraphQL variables: clean lines + warnings in the note.
const items = ($json.data ?? []).filter(d => d.line_item);
const flagged = ($json.data ?? []).filter(d => d.error || (d.warnings && d.warnings.length));
const po = $('Parse AI JSON').first().json;
if (items.length === 0) throw new Error('No matched line items — draft order NOT created. Review the PO manually.');

const poSlug = (po.po_number || '').toUpperCase().replace(/[^A-Z0-9]+/g, '-').replace(/^-|-$/g, '');
const noteLines = [
  `Payment terms: ${String(po.terms || 'net-30').toUpperCase()}`,
  po.po_number ? `PO number: ${po.po_number}` : null,
  po.buyer?.company ? `Buyer: ${po.buyer.company}` : null,
  'Created via n8n (PO Pilot template).',
  flagged.length ? '⚠ NEEDS REVIEW:\n- ' + flagged.map(f => f.error ? `${f.line?.sku || f.line?.title}: ${f.error}` : `${f.sku}: ${f.warnings.join('; ')}`).join('\n- ') : null,
].filter(Boolean);

return [{ json: { variables: { input: {
  lineItems: items.map(i => i.line_item),
  note: noteLines.join('\n'),
  noteAttributes: [
    ...(po.po_number ? [{ key: 'PO Number', value: po.po_number }] : []),
    { key: 'Payment Terms', value: po.terms || 'net-30' },
  ],
  tags: ['wholesale', 'n8n', ...(poSlug ? ['po-' + poSlug] : [])],
  ...(po.buyer?.email ? { email: po.buyer.email } : {}),
} } } }];
